return Array.from({ length: 24 }, (_, i) => ({
  json: {
    cycle: i + 1,
    interval_minutes: 240
  }
}));

// One clean item per cycle for the summary agent:
// the simulation time, Agent 2's report, and EVERY result of this cycle.
const results = $input.all().map(i => i.json);

let time = {};
try { time = $('HTTP Request – Get Current Time').last().json; } catch (e) {}

let cycle = null;
try { cycle = $('Loop Over Items').context.currentRunIndex + 1; } catch (e) {}

let agent2 = [];
try {
  agent2 = $('Call Agent 2 - Disruption Detector').all().map(i => {
    const j = i.json ?? {};
    return {
      status: j.status ?? null,
      has_verified_disruption: j.has_verified_disruption ?? null,
      requires_human_review: j.requires_human_review ?? null,
      disruptions: j.disruptions ?? [],
      suspicious_emails: j.suspicious_emails ?? [],
      rejected_disruptions: j.rejected_disruptions ?? [],
      report: j.report ?? '',
      error: j.error ?? null
    };
  });
} catch (e) {}

// Agent 4's plan (quotes, advisor recommendation, question for the buyer).
// Agent 4 is skipped in cycles with no shortage, and n8n would then hand back
// its output from an OLDER cycle. So we only use it when the cycle stamp on
// Agent 4's input matches the current cycle.
let agent4Ran = false;
let agent4 = null;
try {
  const stamped = $('Add Run ID (to Agent 4)').all().map(i => i.json?.orchestrator_cycle);
  agent4Ran = cycle !== null && stamped.length > 0 && stamped.every(c => c === cycle);
} catch (e) {}
if (agent4Ran) {
  try { agent4 = $("Call 'P4 Agent 4 - V6'").all().map(i => i.json ?? {}); } catch (e) { agent4 = null; }
}

return [{
  json: {
    cycle,
    simulation_time: time,
    agent2_report: agent2,
    agent4_ran_this_cycle: agent4Ran,
    agent4_plan: agent4,
    results_count: results.length,
    results
  }
}];

// Stamps every item with this run's ID. Each specialist agent uses it as its
// memory key, so an agent remembers earlier cycles of THIS run only and a new
// run always starts with a clean memory.
const runId = 'run-' + $execution.id;

return $input.all().map((item, index) => {
  const j = item.json ?? {};

  // Leave blank passthrough items blank.
  if (!Object.keys(j).length) return item;

  return {
    json: { ...j, run_id: runId },
    pairedItem: { item: index }
  };
});

